define([], function() {
    'use strict';
    const init = () => {
    const form = document.querySelector('[data-u-register]');
    if (!form) {
        return;
    }

    const department = form.querySelector('#u-register-department');
    const search = form.querySelector('#u-register-department-search');
    if (department && search) {
        const choices = Array.from(department.options).slice(1).map((option) => ({
            value: option.value,
            label: option.textContent,
        }));
        search.addEventListener('input', () => {
            const query = search.value.trim().toLocaleLowerCase();
            const selected = department.value;
            department.replaceChildren(new Option('Выберите подразделение', ''));
            choices.filter((choice) => choice.label.toLocaleLowerCase().includes(query))
                .forEach((choice) => department.add(new Option(choice.label, choice.value)));
            department.value = choices.some((choice) => choice.value === selected
                && choice.label.toLocaleLowerCase().includes(query)) ? selected : '';
        });
    }

    form.querySelectorAll('[data-u-reveal]').forEach((button) => {
        button.addEventListener('click', () => {
            const input = document.getElementById(button.dataset.uReveal);
            if (!input) {
                return;
            }
            const visible = input.type === 'password';
            input.type = visible ? 'text' : 'password';
            button.textContent = visible ? 'Скрыть' : 'Показать';
            button.setAttribute('aria-pressed', String(visible));
        });
    });

    const firstError = form.querySelector('[aria-invalid="true"]')
        || document.querySelector('.u-register .u-inline-notice');
    if (firstError) {
        firstError.focus();
    }

    form.addEventListener('submit', (event) => {
        const submit = form.querySelector('[type="submit"]');
        if (!submit || !form.checkValidity()) {
            return;
        }
        if (submit.disabled) {
            event.preventDefault();
            return;
        }
        submit.disabled = true;
        submit.textContent = 'Отправляем заявку…';
    });
};
    return {init};
});
